import ValidatorService from"./ValidatorService.js";export default class JsonService{constructor(isOutputKeyValue=true){this._json=[];this._isOutputKeyValue=isOutputKeyValue;this._keyValueJson=[]}get json(){return JSON.parse(JSON.stringify(this._json))}set json(json){switch(typeof json){case"string":this._json=this.strToJson(json);break;default:this._json=json;break}this.keyValueJson=this.getJsonData()}get keyValueJson(){return this._keyValueJson}set keyValueJson(json){this._keyValueJson=this.reduceByNameValue(json)}removeAction(json){json.map((row=>row.filter((field=>!field.name.startsWith("dyjsform_action_")))));return json}getJsonData(){return JSON.parse(JSON.stringify(this.removeAction(this.json)))}addRow(entity){const updatedJson=this.json;updatedJson.push(entity);this.json=updatedJson;return this}removeRow(rowNumber){const updatedJson=this.json;updatedJson.splice(rowNumber,1);this.json=updatedJson;return this}strToJson(str){try{return JSON.parse(str)}catch(error){console.error("Erreur lors du parsing JSON :",error);return null}}reduceByNameValue(json){var reducedJson=[];for(const row of json){let rowJson=[];for(let field of row){rowJson.push({[field["name"]]:field["value"]})}reducedJson.push(rowJson)}return reducedJson}loadOutputJson(outputJson){let json=this.json;if(!this._isOutputKeyValue){this.json=outputJson}else{this.json=this.convertKeyValueJson(outputJson,json)}return this}convertKeyValueJson(KeyValueJson,jsonPattern){while(jsonPattern.length<KeyValueJson.length){const templateRow=jsonPattern[jsonPattern.length-1].map((field=>({...field,value:""})));jsonPattern.push(templateRow)}const updatedJson=jsonPattern.map(((row,rowIndex)=>row.map(((field,fieldIndex)=>{const newField={...field};if(!newField.name.startsWith("dyjsform_action_")){const fieldKey=Object.keys(KeyValueJson[rowIndex][fieldIndex]);const outputJsonValue=Object.keys(KeyValueJson[rowIndex][fieldIndex]).find((key=>key===newField.name))?KeyValueJson[rowIndex][fieldIndex][newField.name]:"";newField.value=outputJsonValue}return newField}))));return updatedJson}updateJsonByField(rowIndex,fieldName,value){let json=this.json;json[rowIndex].forEach((element=>{if(element.name===fieldName){element.value=value}}));const result=this.validate(json,rowIndex);if(result.success){json=this.errorClean(json)}else{json=this.displayError(result,json,rowIndex)}this.json=json;return result}validate(json){const validationResult=ValidatorService.maxCount(json);if(validationResult.valid){return{success:true,errors:null}}else{console.log("Validation échouée :",validationResult.errors);return{success:false,errors:validationResult.errors}}}displayError(validationResult,json,rowIndex=null){if(rowIndex!==null){validationResult.errors.forEach((errorGroup=>{const error=errorGroup.occurrences.find((err=>err.rowIndex===rowIndex));if(error){const entity=json[rowIndex].find((entity=>entity.name===error.name));if(entity){entity.error=errorGroup.message;entity.value=""}}}))}else{validationResult.errors.forEach((errorGroup=>{errorGroup.occurrences.forEach((error=>{const entity=json[error.rowIndex].find((ent=>ent.name===error.name));if(entity){entity.error=errorGroup.message}}))}))}return json}errorClean(json){json=json.map((row=>row.map((entity=>({...entity,error:""})))));return json}writeOutputJson(selector){let output=this.keyValueJson;if(!this._isOutputKeyValue){output=this.json}document.querySelector(selector+" .output").value=JSON.stringify(output,null);return this}}